export type SystemUpdateData = {
  /**
   * SystemUpdateArgs
   *
   * Args for [`system_update`]. Every field is optional; omit-all = read-only
   * state probe (returns current_version / channel / channels / pinned_to /
   * available_versions + pagination).
   *
   * One tool, many surfaces:
   * - orca binary: `channel`, `version` (one-shot, no pin), `dev_source`, `clear_dev_source`
   * - system identity: `hostname`, `fqdn`
   * - addressing overrides: `lan_v4`, `lan_v6`, `tailscale_v4`, `tailscale_v6`
   * - OS package upgrade: `os_packages`
   */
  body: {
    /**
     * Discrete update action. Omit for the default binary/host update flow.
     * `enable_cap` / `disable_cap` / `recheck_cap` drive the per-host
     * capability registry (was `system.capability_{enable,disable,recheck}`);
     * `set_retention` writes retention knobs (was `system.retention_set`).
     */
    action?: SystemUpdateAction | null;
    /**
     * Fleet scope only: proceed even though another fleet roll holds the
     * single-flight lock. For a genuinely stuck lock — a controller killed
     * mid-roll whose lock has not yet aged out. It defeats the guarantee that
     * the fleet is never updated concurrently (#616), so it is never the
     * routine answer to "already in flight".
     */
    break_lock?: boolean;
    /**
     * Switch update channel: stable | beta. On change, applies latest on the
     * new channel. (For local hot-reload dev builds use `orca dev enable` —
     * that is a separate mechanism, not an update channel.)
     */
    channel?: string | null;
    /**
     * Clear the dev-source URL.
     */
    clear_dev_source?: boolean;
    /**
     * Daemon action: "stop" (SIGTERM), "park" (SIGUSR1, release port),
     * or "reclaim" (SIGUSR2, take port back). Was the
     * `system.daemon.{stop,park,reclaim}` family.
     */
    daemon?: string | null;
    /**
     * Skip the plugin phase entirely: report daemon versions only.
     *
     * "What version is every host on" is the commonest question asked of this
     * verb, and answering it does not require enumerating plugins. The full
     * probe costs one `plugin list` plus one dry-run `plugin update` PER
     * PLUGIN per host — around 40 release-source lookups across this fleet —
     * which is what pushes the cheapest, safest form of the call past an MCP
     * client's idle timeout (#626).
     *
     * Read-only by nature, but accepted with `--execute` too, where it means
     * "roll the daemons, leave plugins alone".
     */
    daemons_only?: boolean;
    /**
     * Age cap in days. Pass to set, omit to leave unchanged.
     */
    days?: number | null;
    /**
     * Set the dev-source URL (orca fetches binaries from there instead of GitHub).
     */
    dev_source?: string | null;
    /**
     * Actually apply the channel-latest update. Updates are DRY RUN by default:
     * a bare `orca system update` probes current→latest and reports whether an
     * update is available WITHOUT applying it. Pass `--execute` to apply. An
     * explicit `--version` already implies apply (a deliberate operator action)
     * and does not need this flag.
     */
    execute?: boolean;
    /**
     * Set the host's FQDN setting (no DNS write — UI/peer-display only).
     */
    fqdn?: string | null;
    /**
     * Change this host's OS hostname. Also updates `host.display_name` setting.
     */
    hostname?: string | null;
    /**
     * The system to update. Omit to update them ALL — every joined system's
     * daemon, then every installed plugin on every one. Pass a system id to
     * update exactly that one; orca resolves it and routes there itself, so
     * this names the RESOURCE and is never a host selector (#647).
     *
     * Host-only args (hostname/fqdn/addressing/daemon/action/channel/
     * dev-source/release-source/…) configure THIS system and are rejected on a
     * fleet-wide update rather than silently ignored.
     */
    id?: string | null;
    /**
     * Reserved forward-compat knob for excluding known-edge/unreachable peers.
     * There is no reliable per-peer reachability signal on the roster today, so
     * the fan-out always attempts every joined peer and records a per-host
     * connect error for any that don't answer. Accepted for stability.
     */
    include_edge?: boolean;
    /**
     * Manual LAN IPv4 override.
     */
    lan_v4?: string | null;
    /**
     * Manual LAN IPv6 override.
     */
    lan_v6?: string | null;
    /**
     * Return only the set of selectable channels (in `channels`) plus the
     * host's current channel/version — skips the GitHub version listing
     * entirely. Cheap, cacheable, no network. Ignored if a mutating arg is
     * also present.
     */
    list_channels?: boolean;
    /**
     * Toggle local (loopback) operator login on THIS host. `true` (default
     * when unset) accepts `orca auth login`/MCP/REST login over loopback;
     * `false` refuses it so only browser/remote signin remains. Per-instance
     * security control — disabling it on a host with no browser signin path
     * can lock you out, so re-enable requires an existing session.
     */
    local_login?: boolean | null;
    /**
     * Size cap in megabytes. Pass to set, omit to leave unchanged.
     */
    maxMb?: number | null;
    /**
     * Row count cap. Pass to set, omit to leave unchanged.
     */
    maxRows?: number | null;
    /**
     * Capability provider name for `enable_cap` / `disable_cap` /
     * `recheck_cap` (e.g. `docker`, `proxmox`).
     */
    name?: string | null;
    /**
     * Run the OS package upgrade (apt / apk / brew / unraid plugin). Stays a
     * THIS-SYSTEM action even on a fleet-wide update (the fan-out updates orca
     * daemons and plugins, not every peer's distro).
     */
    os_packages?: boolean;
    /**
     * Peer id to scope this knob to. Omit to write the global default. The CLI
     * long is `--retention-peer` to avoid colliding with the global `--peer`
     * mesh-dispatch flag (#455); the serde/MCP field stays `peer`.
     */
    peer?: string | null;
    /**
     * Fleet scope only: resolve plugins to their newest PRERELEASE (`-rc`)
     * rather than newest stable. Unset defaults to the daemon's update
     * channel — a beta-channel host resolves prereleases automatically (#450)
     * so a fleet already on `-rc` plugins isn't a no-op.
     */
    prerelease?: boolean;
    /**
     * Operator-visible reason for `disable_cap`.
     */
    reason?: string | null;
    /**
     * Force a re-detect of host addressing channels (LAN + Tailscale +
     * settings overrides). Was `system.host.refresh`. Drives the
     * `HostRefreshHook` registered at server startup.
     */
    refresh_host?: boolean;
    /**
     * Set the release SOURCE the daemon lists + downloads updates from — for
     * both the daemon self-update AND plugin installs (which derive their host
     * from this same override). Pass a repo API base URL — GitHub
     * `https://api.github.com/repos/<org>/<repo>` or a Gitea
     * `http(s)://<host>/api/v1/repos/<org>/<repo>` — to pull from the canonical
     * Gitea origin instead of the GitHub mirror (kills mirror-sync lag; every
     * daemon can reach the Gitea origin, and its release reads are public).
     * `http://` is allowed for an internal Gitea over the trusted LAN/mesh. The
     * literal `github` (or `default`) clears the override back to the compiled-in
     * GitHub default. Distinct from `dev_source` (hot-reload dev binaries) — this
     * selects the RELEASE origin.
     */
    release_source?: string | null;
    /**
     * Instance-global: rows kept per job in `scheduler_runs`. Only valid on
     * the global view (omit `peer`); must be positive. Omit to leave unchanged.
     */
    schedulerRunsPerJob?: number | null;
    /**
     * Transitional: `--scope` is gone. It was a caller-chosen mode standing in
     * for addressing — omit `--id` for every system, pass one for a single
     * system (#647). Rejected rather than ignored, because these args carry no
     * `deny_unknown_fields`: a stale client sending `{"scope":"host"}` would
     * otherwise be silently promoted from "just me" to "the whole fleet".
     */
    scope?: string | null;
    /**
     * Act on THIS system only: never fan out, never forward. Internal — it is
     * how the fan-out drives each of its legs, how the mesh liveness probe
     * asks one system about itself, and the terminal spelling an id-addressed
     * call is forwarded as. Because the hop carries it, a forwarded update
     * cannot bounce onward, so no resolution loop is possible.
     */
    self_only?: boolean;
    /**
     * Instance-global: `session_events` retention window in days. Only valid
     * on the global view (omit `peer`). Omit to leave unchanged.
     */
    sessionEventsDays?: number | null;
    /**
     * Manual Tailscale IPv4 override.
     */
    tailscale_v4?: string | null;
    /**
     * Manual Tailscale IPv6 override.
     */
    tailscale_v6?: string | null;
    /**
     * When true, REMOVE any override and fall back to the global / built-in
     * default. Mutually exclusive with the value args.
     */
    unset?: boolean;
    /**
     * Apply a specific version (semver, leading `v` optional) as a one-shot —
     * it does not pin, and never blocks a later update to latest. Omit to
     * update to the channel latest. Updates only apply on this explicit
     * operator action; the daemon never self-applies.
     */
    version?: string | null;
    /**
     * Zero-based page of the version list to return in `available_versions`.
     * The list is channel-scoped and ordered most-recent-first; page 0 is the
     * newest `versions_per_page` releases. `versions_total` reports the full
     * count so callers can drive a pager. Omit → page 0.
     */
    versions_page?: number | null;
    /**
     * Page size for the version list (default 20, capped at 100 — the GitHub
     * listing window). Omit → 20.
     */
    versions_per_page?: number | null;
  };
  path?: never;
  query?: never;
  url: '/api/v1/system.update';
};

export type SystemUpdateErrors = {
  /**
   * Unknown tool
   */
  404: {
    error: string;
  };
  /**
   * Tool execution failed
   */
  500: {
    error: string;
  };
};

export type SystemUpdateError = SystemUpdateErrors[keyof SystemUpdateErrors];

export type SystemUpdateResponses = {
  /**
   * SystemUpdateResult
   *
   * Untagged so the default (`action` omitted) `Update` variant serializes as a
   * bare `SystemUpdateOutput` — preserving every existing wire decoder (the mesh
   * `peer_update_state` cache decodes `SystemUpdateOutput` straight from a `{}`
   * call).
   */
  200: (FleetUpdateOutput & unknown) | SystemUpdateOutput | CapabilityRow | RetentionSetOutput;
};

export type SystemUpdateResponse = SystemUpdateResponses[keyof SystemUpdateResponses];

export type SystemUpdateStatusData = {
  /**
   * FleetUpdateStatusArgs
   */
  body: {
    [key: string]: unknown;
  };
  path?: never;
  query?: never;
  url: '/api/v1/system.update.status';
};

export type SystemUpdateStatusErrors = {
  /**
   * Unknown tool
   */
  404: {
    error: string;
  };
  /**
   * Tool execution failed
   */
  500: {
    error: string;
  };
};

export type SystemUpdateStatusError = SystemUpdateStatusErrors[keyof SystemUpdateStatusErrors];

export type SystemUpdateStatusResponses = {
  /**
   * FleetUpdateStatusOutput
   *
   * Tool result
   */
  200: {
    /**
     * Why there is nothing to report, when there is nothing.
     */
    note?: string | null;
    /**
     * Seconds since the record was last written. A roll updates it after every
     * host, so a small age means one is probably still running and a large one
     * means this is the last completed roll. Stated as an age rather than
     * "running: true/false" because a controller killed mid-roll leaves a
     * record that nothing will ever finish, and claiming it is live would be a
     * guess.
     */
    recordAgeSecs?: number | null;
    /**
     * The roll itself, exactly as the run record has it.
     */
    run?: FleetUpdateOutput | null;
    /**
     * Absolute path of the record this came from.
     */
    runRecord?: string | null;
  };
};

export type SystemUpdateStatusResponse =
  SystemUpdateStatusResponses[keyof SystemUpdateStatusResponses];

